using System.IO;
using System.Net.Http;
using System.Text.Json;
using UniToStudyHub.Models;
namespace UniToStudyHub.Services;
public sealed class MoodleClient:IDisposable
{
 private readonly HttpClient _http; private readonly Uri _baseUri; private readonly string _token; private readonly JsonSerializerOptions _json=new(){PropertyNameCaseInsensitive=true};
 public MoodleClient(string baseUrl,string token){if(!Uri.TryCreate(baseUrl.Trim().TrimEnd('/')+"/",UriKind.Absolute,out var u)||(u.Scheme!="https"&&!(u.Scheme=="http"&&u.IsLoopback))||!string.IsNullOrEmpty(u.UserInfo)||!string.IsNullOrEmpty(u.Query)||!string.IsNullOrEmpty(u.Fragment))throw new ArgumentException("Inserisci la root Moodle HTTPS senza credenziali, query o frammenti.");if(string.IsNullOrWhiteSpace(token))throw new ArgumentException("Token Moodle obbligatorio.");_baseUri=u;_token=token.Trim();_http=new HttpClient(new HttpClientHandler{AllowAutoRedirect=false}){Timeout=TimeSpan.FromSeconds(45)};_http.DefaultRequestHeaders.UserAgent.ParseAdd("UniToStudyHub/0.1");}
 public Task<MoodleSiteInfo> GetSiteInfoAsync(CancellationToken ct=default)=>CallAsync<MoodleSiteInfo>("core_webservice_get_site_info",new Dictionary<string,string>(),ct);
 public Task<List<MoodleCourse>> GetEnrolledCoursesAsync(int id,CancellationToken ct=default)=>CallAsync<List<MoodleCourse>>("core_enrol_get_users_courses",new Dictionary<string,string>{{"userid",id.ToString()}},ct);
 public Task<List<MoodleCourseSection>> GetCourseContentsAsync(int id,CancellationToken ct=default)=>CallAsync<List<MoodleCourseSection>>("core_course_get_contents",new Dictionary<string,string>{{"courseid",id.ToString()}},ct);
 public Task<MoodleCalendarResult> GetCalendarEventsAsync(IEnumerable<int> ids,DateTime from,DateTime to,CancellationToken ct=default){var p=new Dictionary<string,string>{{"options[userevents]","1"},{"options[siteevents]","1"},{"options[timestart]",new DateTimeOffset(from).ToUnixTimeSeconds().ToString()},{"options[timeend]",new DateTimeOffset(to).ToUnixTimeSeconds().ToString()},{"options[ignorehidden]","1"}};var i=0;foreach(var id in ids.Distinct())p[$"events[courseids][{i++}]"]=id.ToString();return CallAsync<MoodleCalendarResult>("core_calendar_get_calendar_events",p,ct);}
 public async Task<List<MoodleForumDiscussion>> GetForumDiscussionsAsync(int id,CancellationToken ct=default){var r=await CallAsync<MoodleForumDiscussionsResult>("mod_forum_get_forum_discussions",new Dictionary<string,string>{{"forumid",id.ToString()},{"sortby","timemodified"},{"sortdirection","DESC"},{"page","0"},{"perpage","25"},{"groupid","-1"}},ct);return r.discussions??new();}
 public async Task DownloadFileAsync(string url,string path,CancellationToken ct=default){if(!Uri.TryCreate(url,UriKind.Absolute,out var source)||!SameOrigin(source,_baseUri))throw new InvalidOperationException("Download bloccato: URL esterno all'istanza Moodle.");var b=new UriBuilder(source);var parts=b.Query.TrimStart('?').Split('&',StringSplitOptions.RemoveEmptyEntries).Where(x=>!Uri.UnescapeDataString(x.Split('=',2)[0]).Equals("token",StringComparison.OrdinalIgnoreCase)).ToList();parts.Add("token="+Uri.EscapeDataString(_token));b.Query=string.Join("&",parts);using var response=await _http.GetAsync(b.Uri,HttpCompletionOption.ResponseHeadersRead,ct);response.EnsureSuccessStatusCode();if(response.Content.Headers.ContentLength is >250_000_000)throw new InvalidOperationException("File oltre 250 MB.");Directory.CreateDirectory(Path.GetDirectoryName(path)!);await using var input=await response.Content.ReadAsStreamAsync(ct);await using var output=new FileStream(path,FileMode.Create,FileAccess.Write,FileShare.None,81920,true);var buffer=new byte[81920];long total=0;int n;while((n=await input.ReadAsync(buffer.AsMemory(),ct))>0){total+=n;if(total>250_000_000)throw new InvalidOperationException("File oltre 250 MB.");await output.WriteAsync(buffer.AsMemory(0,n),ct);}}
 private async Task<T> CallAsync<T>(string function,IDictionary<string,string> parameters,CancellationToken ct){var form=new Dictionary<string,string>(parameters){{"wstoken",_token},{"wsfunction",function},{"moodlewsrestformat","json"}};using var response=await _http.PostAsync(new Uri(_baseUri,"webservice/rest/server.php"),new FormUrlEncodedContent(form),ct);var body=await response.Content.ReadAsStringAsync(ct);if(!response.IsSuccessStatusCode)throw new HttpRequestException($"Moodle HTTP {(int)response.StatusCode}.");using var doc=JsonDocument.Parse(body);if(doc.RootElement.ValueKind==JsonValueKind.Object&&doc.RootElement.TryGetProperty("exception",out _)){var msg=doc.RootElement.TryGetProperty("message",out var m)?m.GetString():"Errore Web Services";throw new InvalidOperationException($"{function}: {msg}. Verifica permessi e token.");}return doc.RootElement.Deserialize<T>(_json)??throw new InvalidOperationException("Risposta Moodle non valida.");}
 private static bool SameOrigin(Uri a,Uri b)=>a.Scheme==b.Scheme&&a.Host==b.Host&&a.Port==b.Port; public void Dispose()=>_http.Dispose();
}